 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]

    # The 5 in the right panel is the path's starting point.
    start = None
    for r in range(h):
        for c in range(8, w):
            if grid[r][c] == 5:
                start = (r, c - 8)
                out[r][c - 8] = 5
                break
        if start is not None:
            break
    if start is None:
        return out

    # Each 3x3 tile is a movement instruction. Read down the left tile
    # column, then down the right tile column, matching all three demos.
    tiles = []
    for left in (0, 4):
        for top in range(0, h - 2, 4):
            vals = [grid[top + dr][left + dc]
                    for dr in range(3) for dc in range(3)
                    if grid[top + dr][left + dc] not in (0, 4, 5)]
            if vals:
                # Tiles are single-color shapes.
                tiles.append(max(set(vals), key=vals.count))

    # Commands draw a colored segment, beginning one row below the previous
    # endpoint. Horizontal commands include the starting column; downward
    # commands continue vertically from that point.
    r, c = start
    for color in tiles:
        if color == 1:
            direction, length = 'R', 3
        elif color == 2:
            direction, length = 'L', 2
        elif color == 3:
            direction, length = 'L', 4
        elif color == 6:
            direction, length = 'D', 2
        else:
            continue

        r += 1
        if direction == 'R':
            for step in range(length):
                cc = c + step
                if 0 <= r < h and 0 <= cc < 7:
                    out[r][cc] = color
            c += length - 1
        elif direction == 'L':
            for step in range(length):
                cc = c - step
                if 0 <= r < h and 0 <= cc < 7:
                    out[r][cc] = color
            c -= length - 1
        else:  # D
            for step in range(length):
                rr = r + step
                if 0 <= rr < h and 0 <= c < 7:
                    out[rr][c] = color
            r += length - 1

    return out

if __name__ == '__main__':
    pass
